import {
  ChatMessageContainer,
  ChatMessagePlacement,
} from './ChatMessageContainer';
import ChatMessageContent from './ChatMessageContent';
import { UIMessage } from '@ai-sdk/react';
import { Collapsible } from '@lablup/ui-common/Collapsible';
import { Spinner } from '@lablup/ui-common/Spinner';
import { Text } from '@lablup/ui-common/Text';
import { Thumbnail } from '@lablup/ui-common/Thumbnail';
import { Token } from '@lablup/ui-common/Token';
import { useTheme } from '@lablup/ui-common/theme';
import { BAIFlex } from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { PaperclipIcon } from 'lucide-react';
import React, { memo, useState } from 'react';
import { useTranslation } from 'react-i18next';

interface FilePart {
  type: 'file';
  url: string;
  mediaType?: string;
  filename?: string;
}

export interface ChatMessageProps {
  message: UIMessage;
  placement?: ChatMessagePlacement;
  extra?: React.ReactNode;
  enableExtraHover?: boolean;
  isStreaming?: boolean;
  avatar?: React.ReactNode;
}

const ChatMessage: React.FC<ChatMessageProps> = ({
  extra,
  message,
  placement,
  enableExtraHover,
  isStreaming,
  avatar,
}) => {
  const { token } = useTheme();
  const { t } = useTranslation();
  const [isHovered, setIsHovered] = useState(false);

  // Extract content and reasoning from parts array
  const content = _.map(
    _.filter(message.parts, (part) => part.type === 'text'),
    (part) => part.text,
  ).join('');

  const reasoningText = _.map(
    _.filter(message.parts, (part) => part.type === 'reasoning'),
    (part) => part.text,
  ).join('');

  // Filter file parts from the message parts array
  const fileParts = _.filter(message.parts, (part) => part.type === 'file');

  // The bubble has no vertical padding; the rendered markdown paragraphs of
  // `content` supply it. When only reasoning is present (e.g. while the model
  // is still thinking), there is no paragraph to provide the bottom gap, so the
  // Collapse has to add it itself.
  const hasContent = !_.isEmpty(_.trim(content));

  return (
    <ChatMessageContainer
      placement={placement}
      avatar={avatar}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {_.map(fileParts, (part: FilePart, index) => {
        if (part.type !== 'file') {
          return null;
        }

        const filename =
          part.filename || part.url?.split('/').pop() || `file-${index}`;

        return part.mediaType?.toLowerCase().startsWith('image/') ? (
          <BAIFlex
            key={`${message?.id}-${index}`}
            style={{
              border: 'none',
              textAlign: 'end',
            }}
            align="end"
          >
            <Thumbnail
              src={part?.url}
              alt={filename}
              style={{
                maxWidth: '50vw',
                maxHeight: '12vh',
                borderRadius: token('--radius-inner'),
              }}
            />
          </BAIFlex>
        ) : (
          // PILOT-DECISION: `@ant-design/x`'s `FileCard` (icon + name +
          // description + download link) has no Astryx card equivalent — the
          // closest primitive is `Token`, which carries the same three
          // affordances (leading icon, file name, `href` to the attachment)
          // in a smaller, list-friendly shape. The redundant `description`
          // (it repeated the file name) is dropped.
          <Token
            key={`${message?.id}-${index}`}
            label={filename}
            description={filename}
            icon={<PaperclipIcon size="1em" />}
            href={part?.url}
          />
        );
      })}
      <BAIFlex
        align="stretch"
        direction="column"
        style={{
          borderRadius: token('--radius-inner'),
          borderColor: token('--color-border'),
          borderWidth: token('--border-width'),
          padding: '1em',
          paddingTop: 0,
          paddingBottom: 0,
          backgroundColor: token('--color-background-popover'),
          maxWidth: '100%',
          width: _.trim(reasoningText) ? '100%' : 'auto',
        }}
      >
        {_.trim(reasoningText) && (
          <Collapsible
            defaultIsOpen={false}
            style={{
              marginTop: token('--spacing-4'),
              marginBottom: hasContent ? 0 : token('--spacing-4'),
              width: '100%',
            }}
            trigger={
              !hasContent ? (
                <BAIFlex gap="xs">
                  <Text>{t('chatui.Thinking')}</Text>
                  <Spinner size="sm" />
                </BAIFlex>
              ) : (
                <Text>{t('chatui.ViewReasoning')}</Text>
              )
            }
          >
            <ChatMessageContent isStreaming={isStreaming}>
              {reasoningText}
            </ChatMessageContent>
          </Collapsible>
        )}
        <ChatMessageContent isStreaming={isStreaming}>
          {content + (isStreaming ? '\n' : '')}
        </ChatMessageContent>
      </BAIFlex>
      <BAIFlex
        style={{
          fontSize: token('--font-size-sm'),
          ...(enableExtraHover
            ? {
                opacity: isHovered ? 1 : 0,
                transition: 'opacity 0.2s',
                transitionDelay: isHovered ? '0s' : '0.2s',
              }
            : {}),
        }}
      >
        {extra}
      </BAIFlex>
    </ChatMessageContainer>
  );
};

export default memo(ChatMessage);
